    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum BusinessType {\n  SHOP\n  EDUCATION\n  CONSULTING\n}\n\nenum PlanTier {\n  STARTER\n  BUSINESS\n  PRO\n}\n\nenum UserRole {\n  OWNER\n  EMPLOYEE\n}\n\nenum LookupKind {\n  ORDER\n  ACCESS\n}\n\nenum FormFieldType {\n  TEXT\n  NUMBER\n  PHONE\n  SINGLE_CHOICE\n  MULTI_CHOICE\n  FILE\n}\n\nenum BroadcastStatus {\n  DRAFT\n  QUEUED\n  SENDING\n  DONE\n  FAILED\n}\n\n/// Platform operator accounts (Telebino staff) — fully separate from the\n/// business-scoped User model, with its own email/password login and JWT.\nmodel AdminUser {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  name         String\n  createdAt    DateTime @default(now())\n}\n\nmodel Business {\n  id                   String       @id @default(cuid())\n  name                 String\n  type                 BusinessType\n  planTier             PlanTier     @default(STARTER)\n  /// Dev-only placeholder for real billing status (set true by the manual\n  /// plan-switch endpoint). Gates bot replies past the 5 free trial messages.\n  isSubscriptionActive Boolean      @default(false)\n  createdAt            DateTime     @default(now())\n  updatedAt            DateTime     @updatedAt\n\n  users               User[]\n  products            Product[]\n  faqEntries          FaqEntry[]\n  lookupEntries       LookupEntry[]\n  customers           Customer[]\n  forms               FormDef[]\n  bots                Bot[]\n  broadcasts          Broadcast[]\n  unansweredQuestions UnansweredQuestion[]\n}\n\nmodel User {\n  id         String   @id @default(cuid())\n  phone      String   @unique\n  role       UserRole @default(OWNER)\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id])\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n}\n\nmodel Product {\n  id          String   @id @default(cuid())\n  businessId  String\n  business    Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  name        String\n  description String?\n  price       Int?\n  imageUrl    String?\n  /// Business-type-specific extras (stock/category for shops, grade/subject/accessType for education, duration for consulting)\n  attributes  Json?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  lookupEntries LookupEntry[]\n\n  @@index([businessId])\n}\n\nmodel FaqEntry {\n  id               String   @id @default(cuid())\n  businessId       String\n  business         Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  question         String\n  alternatePhrases String[]\n  answer           String\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([businessId])\n}\n\nmodel LookupEntry {\n  id             String     @id @default(cuid())\n  businessId     String\n  business       Business   @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  kind           LookupKind\n  identifier     String\n  status         String\n  customerPhone  String?\n  note           String?\n  notifyOnUpdate Boolean    @default(true)\n  productId      String?\n  /// Kept even if the product is later deleted — the order/access record itself is historical.\n  product        Product?   @relation(fields: [productId], references: [id], onDelete: SetNull)\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  @@unique([businessId, kind, identifier])\n  @@index([businessId, kind])\n  @@index([productId])\n}\n\nmodel Customer {\n  id               String   @id @default(cuid())\n  businessId       String\n  business         Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  telegramUserId   String\n  telegramUsername String?\n  phone            String?\n  messageCount     Int      @default(0)\n  blocked          Boolean  @default(false)\n  firstSeenAt      DateTime @default(now())\n  lastSeenAt       DateTime @default(now())\n\n  formSubmissions FormSubmission[]\n\n  @@unique([businessId, telegramUserId])\n  @@index([businessId])\n}\n\nmodel FormDef {\n  id         String   @id @default(cuid())\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  title      String\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  fields      FormField[]\n  submissions FormSubmission[]\n\n  @@index([businessId])\n}\n\nmodel FormField {\n  id       String        @id @default(cuid())\n  formId   String\n  form     FormDef       @relation(fields: [formId], references: [id], onDelete: Cascade)\n  label    String\n  type     FormFieldType\n  required Boolean       @default(true)\n  options  String[]\n  order    Int           @default(0)\n\n  @@index([formId])\n}\n\nmodel FormSubmission {\n  id         String    @id @default(cuid())\n  formId     String\n  form       FormDef   @relation(fields: [formId], references: [id], onDelete: Cascade)\n  customerId String?\n  customer   Customer? @relation(fields: [customerId], references: [id])\n  answers    Json\n  createdAt  DateTime  @default(now())\n\n  @@index([formId])\n}\n\nmodel Bot {\n  id            String   @id @default(cuid())\n  businessId    String\n  business      Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  token         String\n  telegramBotId String\n  username      String\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([businessId])\n}\n\nmodel Broadcast {\n  id         String          @id @default(cuid())\n  businessId String\n  business   Business        @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  text       String\n  mediaUrl   String?\n  status     BroadcastStatus @default(DRAFT)\n  sentCount  Int             @default(0)\n  failCount  Int             @default(0)\n  createdAt  DateTime        @default(now())\n  updatedAt  DateTime        @updatedAt\n\n  @@index([businessId])\n}\n\nmodel UnansweredQuestion {\n  id         String   @id @default(cuid())\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  question   String\n  askedAt    DateTime @default(now())\n\n  @@index([businessId])\n}\n",
